function Atomic([string]$P,[byte[]]$B){$t=$P+'.staff-native.tmp';$old=$P+'.staff-native.replaced.tmp';if((Test-Path $t) -or (Test-Path $old)){throw 'Previous atomic write needs inspection'};[IO.File]::WriteAllBytes($t,$B);if(Test-Path $P){[IO.File]::Replace($t,$P,$old);Remove-Item -LiteralPath $old -Force}else{[IO.File]::Move($t,$P)}}
function Save([string]$P,$V){Atomic $P ([Text.Encoding]::UTF8.GetBytes(($V|ConvertTo-Json -Depth 64)))}
function Get-StaffNativeContainer([string]$N){return (ConvertFrom-Json -InputObject (Invoke-StaffNativeDocker @('inspect',$N)))[0]}
function Get-StaffNativeImage([string]$N){return (ConvertFrom-Json -InputObject (Invoke-StaffNativeDocker @('image','inspect',$N)))[0]}
