function Protected{foreach($old in $m.protected){$n=Get-StaffNativeContainer $old.name;if($n.Id -ne $old.id -or $n.Image -ne $old.image -or $n.State.StartedAt -ne $old.startedAt -or -not $n.State.Running){throw ('Protected service changed: '+$old.name)}}}
