function NodeInApi([string]$File,[string[]]$Arguments=@()){$target='/tmp/staff-native-password-'+[IO.Path]::GetFileName($File);$null=Invoke-StaffNativeDocker @('cp',$File,('clinic-crm-api:'+$target));return Invoke-StaffNativeDocker (@('exec','clinic-crm-api','node',$target)+$Arguments)}
